function CampusTable({campuses,onDetails,compact=false,onDelete}: {campuses:Campus[];onDetails:(record:Campus)=>void;compact?:boolean;onDelete?:(record:Campus)=>void}) { const [search,setSearch]=useState(''),[filter,setFilter]=useState('All statuses'),[sort,setSort]=useState(false),[page,setPage]=useState(1);const rows=useMemo(()=>campuses.filter(c=>(c.name+c.code+c.university).toLowerCase().includes(search.toLowerCase())&&(filter==='All statuses'||c.status===filter)).sort((a,b)=>sort?a.name.localeCompare(b.name):0),[campuses,search,filter,sort]);const visible=compact?rows:rows.slice((page-1)*5,page*5);return <><div className="table-toolbar"><div className="table-search"><Search size={15}/><input placeholder="Search campuses..." value={search} onChange={e=>{setSearch(e.target.value);setPage(1)}}/></div><select className="filter-select" value={filter} onChange={e=>setFilter(e.target.value)}><option>All statuses</option><option>Active</option><option>Review</option></select>{!compact&&<button className="outline-button" onClick={()=>exportCSV(rows)}><Download size={14}/> Export CSV</button>}<button className="icon-button filter-button" aria-label="More filters"><Filter size={15}/></button></div><div className="table-scroll"><table className="data-table"><thead><tr><th><button className="sort-button" onClick={()=>setSort(v=>!v)}>Campus <ArrowUpRight size={12}/></button></th><th>Code</th>{!compact&&<th>University</th>}<th>Students</th><th>Faculty</th><th>Programs</th><th>Status</th><th></th></tr></thead><tbody>{visible.map(row=><tr key={row.code}><td><button className="campus-name" onClick={()=>onDetails(row)}><span className="campus-mini-icon"><Building2 size={15}/></span>{row.name}</button></td><td><code>{row.code}</code></td>{!compact&&<td>{row.university}</td>}<td>{number(row.students)}</td><td>{number(row.faculty)}</td><td>{row.programs}</td><td><span className={`status ${row.status==='Active'?'status-active':'status-review'}`}><i/>{row.status}</span></td><td><div className="row-menu"><button className="icon-button" title="View details" onClick={()=>onDetails(row)}><Eye size={15}/></button>{onDelete&&<button className="icon-button" title="Delete" onClick={()=>onDelete(row)}><Ellipsis size={16}/></button>}</div></td></tr>)}</tbody></table>{visible.length===0&&<div className="empty-state"><Building2 size={23}/><b>No campuses found</b><span>Try adjusting your search or filters.</span></div>}</div>{!compact&&<div className="pagination"><span>Showing <b>{rows.length?Math.min((page-1)*5+1,rows.length):0}–{Math.min(page*5,rows.length)}</b> of <b>{rows.length}</b> campuses</span><div><button className="icon-button" aria-label="Previous page" onClick={()=>setPage(p=>Math.max(1,p-1))}><ChevronLeft size={16}/></button><button className="page-number">{page}</button><button className="icon-button" aria-label="Next page" onClick={()=>setPage(p=>Math.min(Math.ceil(rows.length/5)||1,p+1))}><ChevronRight size={16}/></button></div></div>}</> }

function exportCSV(rows:Campus[]) {const head=['Campus Name','Campus Code','University','Students','Faculty','Departments','Programs','Status'];const csv=[head,...rows.map(c=>[c.name,c.code,c.university,c.students,c.faculty,c.departments,c.programs,c.status])].map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.download='techcoder-campuses.csv';link.click();URL.revokeObjectURL(link.href)}

