function StudentModulePage({title,records,onAction}:{title:string;records?:DemoRecord[];onAction:(label:string)=>void}) {
 const config=studentModuleInfo(title),rows=records||config.records
 const [search,setSearch]=useState(''),[selected,setSelected]=useState<DemoRecord|null>(null)
 const isLibrary=title.toLowerCase().includes('library')
 const action=isLibrary?'Reserve / renew a book':title.toLowerCase().includes('attendance')?'Request attendance correction':title.toLowerCase().includes('certificate')?'Apply for a certificate':title.toLowerCase().includes('assignment')?'View assignment instructions':title.toLowerCase().includes('fee')?'Request fee concession / refund':'Open student action'
 const shown=rows.filter(row=>(row.name+' '+row.detail+' '+row.status).toLowerCase().includes(search.toLowerCase()))
 return <><PageHeader eyebrow="STUDENT PORTAL" title={isLibrary?'My Library':title} description={config.purpose}/><div className="module-stats student-module-stats">{config.kpis.map(([label,value],i)=><div key={label}><span className={`mini-stat-icon ${['purple','green','amber','blue'][i]}`}><BookOpen size={16}/></span><small>{label}</small><b>{value}</b><i>My student record</i></div>)}</div><section className="panel generic-module-panel student-module-panel"><div className="module-panel-heading"><div><h3>{isLibrary?'My books & library access':`My ${title.replace(/^Student /,'').toLowerCase()} records`}</h3><p>Personal information and actions available to your student account</p></div><span className="demo-label">STUDENT VIEW</span></div><div className="table-toolbar"><div className="table-search"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search my records..."/></div><button className="button button-primary" onClick={()=>onAction(action)}><Plus size={14}/>{action}</button></div><div className="module-card-list">{shown.map((row,i)=><div className="module-record" key={row.id}><div className={`record-symbol record-${i%4}`}><BookOpen size={17}/></div><button className="record-copy record-select" onClick={()=>setSelected(row)}><b>{row.name}</b><small>{row.detail}</small></button><span className={`status ${/active|ready|paid|issued|available|submitted|complete|safe/i.test(row.status)?'status-active':'status-review'}`}><i/>{row.status}</span><button className="icon-button" title="View details" onClick={()=>setSelected(row)}><Eye size={15}/></button></div>)}</div>{shown.length===0&&<div className="empty-state"><Search size={20}/><b>No matching student records</b><span>Search term badal kar dekhein.</span></div>}<div className="pagination"><span>Showing <b>{shown.length}</b> of <b>{rows.length}</b> personal records</span><button className="outline-button" onClick={()=>onAction(action)}><Plus size={14}/>{action}</button></div></section>{selected&&<section className="panel selected-record"><div><span className="eyebrow">MY RECORD</span><h3>{selected.name}</h3><p>{selected.detail}</p><span className="status status-active"><i/>{selected.status}</span></div><button className="icon-button" onClick={()=>setSelected(null)} aria-label="Close details"><X size={17}/></button></section>}<section className="module-help panel"><span className="help-icon"><CircleHelp size={17}/></span><div><b>{isLibrary?'Student ka library access':'Yeh section kis kaam ka hai?'}</b><p>{isLibrary?'Student yahan catalogue browse, apni issued books/due dates dekh aur reserve/renew request bhej sakta hai. Books add karna, issue/return approve karna aur catalogue maintain karna Librarian/Library Admin ka kaam hai.':config.purpose}</p></div></section><div className="module-note"><ShieldCheck size={16}/><div><b>Student account view</b><span>Yahan sirf student ke apne records/actions hain. Management controls staff/admin dashboard mein rahenge.</span></div></div></>
}

function ModulePage({title,campuses,records,persistent,onAdd,onDetails,onDelete}:{title:string;campuses:Campus[];records?:DemoRecord[];persistent:boolean;onAdd:()=>void;onDetails:(record:Campus)=>void;onDelete:(record:Campus)=>void}) {
 const isCampus=/campus|college/i.test(title), config=moduleInfo(title), rows=records||config.records
 const [search,setSearch]=useState(''),[selected,setSelected]=useState<DemoRecord|null>(null)
 const shown=rows.filter(row=>(row.name+' '+row.detail+' '+row.status).toLowerCase().includes(search.toLowerCase()))
 return <><PageHeader eyebrow="SUPER ADMIN WORKSPACE" title={title} description={config.purpose} action={isCampus?'Add campus':`Add ${title.replace(/s$/,'')}`} onAction={onAdd}/><div className="module-stats">{config.kpis.map(([label,value],i)=><div key={label}><span className={`mini-stat-icon ${['purple','green','amber','blue'][i]}`}><Layers3 size={16}/></span><small>{label}</small><b>{value}</b><i>Demo data ? 2026?27</i></div>)}</div>{isCampus?<section className="panel module-table-panel"><div className="module-panel-heading"><div><h3>Campus directory</h3><p>Campus operations and enrollment summary</p></div><button className="outline-button" onClick={()=>exportCSV(campuses)}><Download size={14}/> Export CSV</button></div><CampusTable campuses={campuses} onDetails={onDetails} onDelete={onDelete}/></section>:<section className="panel generic-module-panel"><div className="module-panel-heading"><div><h3>{title} · {persistent?'University records':'Demo records'}</h3><p>{persistent?'Records saved for this university':'Har module ka apna sample data aur workflow hai'}</p></div><span className="demo-label">{persistent?'DATABASE':'DEMO DATA'}</span></div><div className="table-toolbar"><div className="table-search"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={`Search in ${title.toLowerCase()}...`}/></div><button className="outline-button" onClick={()=>setSelected(null)}>Clear selection</button></div><div className="module-card-list">{shown.map((row,i)=><div className="module-record" key={row.id}><div className={`record-symbol record-${i%4}`}><FileText size={17}/></div><button className="record-copy record-select" onClick={()=>setSelected(row)}><b>{row.name}</b><small>{row.detail}</small></button><span className={`status ${/active|ready|paid|published|issued|connected|healthy|met|complete/i.test(row.status)?'status-active':'status-review'}`}><i/>{row.status}</span><button className="icon-button" title="View details" onClick={()=>setSelected(row)}><Eye size={15}/></button></div>)}</div>{shown.length===0&&<div className="empty-state"><Search size={20}/><b>No matching records</b><span>Search term badal kar dekhein.</span></div>}<div className="pagination"><span>Showing <b>{shown.length}</b> of <b>{rows.length}</b> {title.toLowerCase()} records</span><button className="outline-button" onClick={onAdd}><Plus size={14}/> Add record</button></div></section>}{selected&&<section className="panel selected-record"><div><span className="eyebrow">SELECTED RECORD</span><h3>{selected.name}</h3><p>{selected.detail}</p><span className="status status-active"><i/>{selected.status}</span></div><button className="icon-button" onClick={()=>setSelected(null)} aria-label="Close record details"><X size={17}/></button></section>}<section className="module-help panel"><span className="help-icon"><CircleHelp size={17}/></span><div><b>Is module ka kaam</b><p>{config.purpose} {persistent?'Records aur form submissions is university ke database mein save hote hain.':'Abhi yeh sample data/local demo view hai.'}</p></div></section><div className="module-note"><ShieldCheck size={16}/><div><b>{persistent?'University database connected':'Demo workflow'}</b><span>{persistent?'Search and new records use the selected university database.':'Is module ka database workflow abhi connect nahi hai.'}</span></div></div></>
}

type FormField = { label: string; options?: string[]; optionValues?:string[]; placeholder?: string; inputType?:string }
function fieldHelp(label:string):string {
 const t=label.toLowerCase()
 if(t.includes('department'))return 'Is record ko jis academic department se jodna hai, woh chuniye.'
 if(t.includes('hod')||t.includes('head of'))return 'Department ke zimmedar Head of Department ko assign karein.'
 if(t.includes('session')||t.includes('academic year'))return 'Yeh record kis academic saal/semester mein valid hoga.'
 if(t.includes('campus'))return 'Record ka campus/location. Isse campus-wise reports filter hoti hain.'
 if(t.includes('status'))return 'Active record use mein rahega; Draft/Review abhi process mein hota hai.'
 if(t.includes('name'))return 'List aur search mein pehchan ke liye naam likhein.'
 if(t.includes('code')||t.includes('id')||t.includes('reference'))return 'Unique reference se record ko baad mein jaldi dhoondh sakte hain.'
 if(t.includes('email'))return 'Official contact/login address. Demo mein email nahi bheja jaata.'
 if(t.includes('amount')||t.includes('fee'))return 'Rupees mein amount enter karein; yeh demo calculation hai.'
 if(t.includes('date')||t.includes('from')||t.includes('to'))return 'Effective date ya workflow ki time limit set karein.'
 if(t.includes('program')||t.includes('course'))return 'Jis course/program ke saath yeh entry sambandhit hai, use chuniye.'
 if(t.includes('faculty')||t.includes('staff')||t.includes('employee'))return 'Assigned faculty/staff member choose karein.'
 if(t.includes('student')||t.includes('applicant'))return 'Is request/application se sambandhit student ki details.'
 if(t.includes('duration'))return 'Course ya activity kitne samay tak chalegi.'
 if(t.includes('capacity')||t.includes('seats'))return 'Maximum seats/participants ki sankhya.'
 return 'Is module ke record ko sahi category mein rakhne ke liye yeh field bharein.'
}
function fieldsFor(title: string): FormField[] {
  const t = title.toLowerCase()
  if(t.includes('request:')&& (t.includes('reserve')||t.includes('renew')))return [{label:'Book title',placeholder:'Search or enter a book title'},{label:'Request type',options:['Reserve this book','Renew my current loan']},{label:'Preferred date',placeholder:'Select pickup / renewal date'},{label:'Notes',placeholder:'Optional request note'}]
  if(t.includes('request:')&&t.includes('attendance'))return [{label:'Subject / class',options:['Data Structures','Database Systems','Computer Networks']},{label:'Lecture date',placeholder:'Select the class date'},{label:'Correction reason',options:['Marked absent by mistake','Approved medical leave','Other']},{label:'Details',placeholder:'Explain the correction request'}]
  if(t.includes('request:')&&t.includes('certificate'))return [{label:'Certificate type',options:['Bonafide','Character','Transfer','Migration','Transcript']},{label:'Purpose',placeholder:'Why do you need this certificate?'},{label:'Required by date',placeholder:'Select a date'},{label:'Delivery preference',options:['Digital download','Collect from Registrar']}]
  if(t.includes('request:')&&t.includes('fee'))return [{label:'Request type',options:['Fee concession','Installment plan','Refund request']},{label:'Amount (₹)',placeholder:'Enter amount if applicable'},{label:'Reason',placeholder:'Explain your request'},{label:'Supporting detail',placeholder:'Add reference or notes'}]
  if(t.includes('request:'))return [{label:'Request / action name',placeholder:'Describe your request'},{label:'Subject or reference',placeholder:'Enter class, course or reference'},{label:'Preferred date',placeholder:'Select date if applicable'},{label:'Details',placeholder:'Explain what you need'}]
  if (t.includes('create hod profile')) return [{label:'HOD full name',placeholder:'Enter the department head name'},{label:'Official email',placeholder:'hod@techcoder.edu'},{label:'Department',options:['Computer Science','Business Administration','Applied Sciences']},{label:'Campus',options:['Main Campus','North Valley Institute','Lakeside College']},{label:'Academic session',options:['2026–27','2025–26']}]
  if (t.includes('create user profile')) return [{label:'Full name',placeholder:'Enter staff/user full name'},{label:'Official email',placeholder:'name@techcoder.edu',inputType:'email'},{label:'Role',options:['University Administrator','Registrar','HOD','Faculty','Student','Finance Officer','Librarian','Admission Officer','Controller of Examinations']},{label:'Temporary password',placeholder:'At least 12 characters',inputType:'password'}]
  if (t.includes('hod')) return [{label:'Department',options:['Computer Science','Business Administration','Applied Sciences']},{label:'Head of Department',options:['Dr. Aditi Rao','Dr. Vikram Sen','Dr. Neha Iyer']},{label:'Academic session',options:['2026–27','2025–26']},{label:'Effective from',placeholder:'Select effective date'},{label:'Status',options:['Active','Draft']},{label:'Notes',placeholder:'Add allocation notes'}]
  if (t.includes('department')) return [{label:'Department name',placeholder:'e.g. Computer Science'},{label:'Department code',placeholder:'e.g. CSE'},{label:'Faculty / School',options:['School of Engineering','School of Business','School of Arts & Sciences']},{label:'Head of department',options:['Select HOD','Dr. Aditi Rao','Dr. Vikram Sen']},{label:'Campus',options:['Main Campus','North Valley Institute','Lakeside College']},{label:'Status',options:['Active','Draft']}]
  if (t.includes('program') || t.includes('course') || t.includes('curriculum') || t.includes('specialization')) return [{label:'Program / course name',placeholder:'e.g. B.Tech Computer Science'},{label:'Program level',options:['Undergraduate','Postgraduate','Diploma','Research']},{label:'Department',options:['Computer Science','Business Administration','Applied Sciences']},{label:'Duration',placeholder:'e.g. 4 years'},{label:'Academic session',options:['2026–27','2025–26']},{label:'Intake capacity',placeholder:'Number of seats'}]
  if (t.includes('student') || t.includes('admission') || t.includes('application')) return [{label:'Student full name',placeholder:'Enter student name'},{label:'Application / enrollment ID',placeholder:'Auto-generated if blank'},{label:'Program',options:['B.Tech Computer Science','MBA','B.Sc. Data Science']},{label:'Campus',options:['Main Campus','North Valley Institute','Lakeside College']},{label:'Academic session',options:['2026–27','2025–26']},{label:'Email address',placeholder:'student@example.edu'}]
  if (t.includes('university')) return [{label:'University name',placeholder:'Enter registered university name'},{label:'University code',placeholder:'e.g. TCU-UNI-001'},{label:'Registration number',placeholder:'Official registration number'},{label:'Accreditation',options:['NAAC A++','NAAC A+','NAAC A','In progress']},{label:'Academic session',options:['2026–27','2025–26']},{label:'Contact email',placeholder:'admin@university.edu'}]
  if (t.includes('campus') || t.includes('college')) return [{label:'Campus name',placeholder:'e.g. East City Campus'},{label:'Campus code',placeholder:'Auto-generated if blank'},{label:'University',options:['TechCoder University','Meridian Institute']},{label:'Campus type',options:['Main campus','Constituent college','Affiliated college']},{label:'Academic session',options:['2026–27','2025–26']},{label:'City',placeholder:'Campus city'}]
  if (t.includes('user') || t.includes('role') || t.includes('permission')) return [{label:'Full name',placeholder:'Enter staff name'},{label:'Email address',placeholder:'name@techcoder.edu'},{label:'Role',options:allRoles},{label:'Campus access',options:['All campuses','Main Campus','North Valley Institute']},{label:'Status',options:['Active','Invite pending']}]
  if (t.includes('session') || t.includes('calendar') || t.includes('semester') || t.includes('timetable')) return [{label:'Session / event name',placeholder:'e.g. Academic Session 2026–27'},{label:'Academic year',options:['2026–27','2025–26']},{label:'Start date',placeholder:'Select start date'},{label:'End date',placeholder:'Select end date'},{label:'Campus',options:['All campuses','Main Campus','North Valley Institute']},{label:'Status',options:['Draft','Published']}]
  if (t.includes('fee') || t.includes('finance') || t.includes('refund') || t.includes('scholarship')) return [{label:'Request / account name',placeholder:'Enter student or account name'},{label:'Reference ID',placeholder:'Auto-generated if blank'},{label:'Request type',options:['Fee payment','Refund request','Scholarship','Other']},{label:'Amount (₹)',placeholder:'Enter amount'},{label:'Campus',options:['Main Campus','North Valley Institute','Lakeside College']},{label:'Status',options:['Pending review','Approved','On hold']}]
  if (t.includes('staff') || t.includes('faculty') || t.includes('hr') || t.includes('hod allocation')) return [{label:'Staff full name',placeholder:'Enter faculty or staff name'},{label:'Employee ID',placeholder:'e.g. EMP-1024'},{label:'Department',options:['Computer Science','Business Administration','Applied Sciences']},{label:'Designation',options:['Faculty','Department HOD','Administrative staff']},{label:'Campus',options:['Main Campus','North Valley Institute']},{label:'Joining date',placeholder:'Select joining date'}]
  return [{label:'Record name',placeholder:`Enter ${title.toLowerCase()} name`},{label:'Reference code',placeholder:'Auto-generated if blank'},{label:'Category',options:['General','Academic','Administrative','Other']},{label:'Campus',options:['All campuses','Main Campus','North Valley Institute']},{label:'Academic session',options:['2026–27','2025–26']},{label:'Status',options:['Active','Draft','Under review']}]
}

function Modal({title,kind,record,module,persistent,universityOptions=[],onClose,onSubmit,onCreateHod,onQuickAction}: {title:string;kind:string;record?:Campus;module?:string;persistent?:boolean;universityOptions?:TenantOption[];onClose:()=>void;onSubmit:(data:FormData,module?:string)=>Promise<void>|void;onCreateHod:(data:FormData)=>Promise<void>|void;onQuickAction:(item:string)=>void}) {
  const [saved,setSaved]=useState(false),[saving,setSaving]=useState(false),[error,setError]=useState('')
  const campusForm=/campus|college/i.test(title)
  const fields=fieldsFor(title).map(field=>campusForm&&field.label==='University'?{...field,options:universityOptions.map(item=>item.name),optionValues:universityOptions.map(item=>item.id)}:field)
  return <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-heading"><div><span className="modal-icon"><Sparkles size={17}/></span><div><h3>{title}</h3><p>{kind==='details'?'Campus information':kind==='quick'?'Choose a workflow to get started':saved?persistent?'Saved to the university database':'Demo record added to this module':kind==='student-request'?'Student request form · frontend demo':campusForm?(persistent?'Connected campus form':'Select a registered university first'):persistent?'University database form':'A frontend demo form'}</p></div></div><button className="icon-button" onClick={onClose} aria-label="Close"><X size={18}/></button></div>{kind==='details'&&record?<div className="detail-grid">{[['Campus code',record.code],['University',record.university],['Students',number(record.students)],['Faculty',number(record.faculty)],['Departments',record.departments],['Programs',record.programs],['Status',record.status]].map(([k,v])=><div key={k}><small>{k}</small><b>{v}</b></div>)}</div>:kind==='quick'?<div className="quick-modal-grid">{['Register University','Add Campus','Create Department','Create Program','Add User','Generate Report','Academic Session Setup','Student Registration'].map(item=><button key={item} onClick={()=>onQuickAction(item)}><span><Plus size={15}/></span>{item}<ArrowRight size={14}/></button>)}</div>:kind==='messages'?<div className="message-list">{['Admissions team: Review 6 new applications','Finance office: Monthly collection report is ready','Registrar: Academic calendar approved'].map((m,i)=><div key={m}><span className="avatar">{['AT','FO','RG'][i]}</span><div><b>{m.split(':')[0]}</b><small>{m.split(': ')[1]}</small></div><small>{i===0?'9:42 AM':'Yesterday'}</small></div>)}</div>:<form onSubmit={async e=>{e.preventDefault();setError('');setSaving(true);const form=new FormData(e.currentTarget);try{if(kind==='role-create')await onCreateHod(form);else {const statusIndex=fields.findIndex(field=>field.label.toLowerCase()==='status');if(statusIndex>=0)form.set('demo-status',String(form.get(`field-${statusIndex}`)||''));if(kind==='student-request'){form.set('demo-status','Request submitted');form.set('demo-detail',fields.map((field,index)=>[field.label,String(form.get(`field-${index}`)||'')] as const).filter(([,value])=>value).map(([label,value])=>`${label}: ${value}`).join(' · '))}await onSubmit(form,module)}if(!campusForm)setSaved(true)}catch(err){setError(err instanceof Error?err.message:'Save failed. Please try again.')}finally{setSaving(false)}}}>{fields.map((field,i)=><label key={field.label}>{field.label}<small className="field-help">{fieldHelp(field.label)}</small>{field.options?<select name={`field-${i}`} required><option value="">Select {field.label.toLowerCase()}</option>{field.options.map((option,optionIndex)=><option key={option} value={field.optionValues?.[optionIndex]||option}>{option}</option>)}</select>:<input type={field.inputType||'text'} name={campusForm&&i===0?'name':`field-${i}`} required={i===0} minLength={field.inputType==='password'?12:undefined} placeholder={field.placeholder}/>}</label>)}<label>Description / notes<small className="field-help">Extra context that helps identify or review this record.</small><textarea name="description" rows={2} placeholder="Add any relevant details..."/></label><div className="demo-form-note"><ShieldCheck size={14}/> {kind==='role-create'?'This user profile is saved locally and can be selected in Demo role login.':kind==='student-request'?'Request is stored in your student demo list only; staff approval routing is not connected.':campusForm?(persistent?'Campus is saved to the selected university database.':'Select a university to save this campus.'):persistent?'Save writes this module record to the selected university database.':'No university is connected yet; register one before saving records.'}</div>{error&&<div className="platform-error" role="alert">{error}</div>}{saved&&<div className="form-saved"><Check size={14}/>{persistent?'Record saved in the university database.':'Demo record added to the module.'} Close this window to see it in the list.</div>}<div className="modal-actions"><button type="button" className="outline-button" onClick={onClose}>Cancel</button><button type="submit" disabled={saving} className="button button-primary">{saving?<LoaderCircle size={15}/>:<Check size={15}/>} {saving?'Saving…':saved?'Add another':kind==='student-request'?'Submit request':'Save changes'}</button></div></form>}</section></div>
}

function SuperAdminLogin({onLogin}:{onLogin:(email:string,password:string,mode:'PLATFORM'|'INSTITUTIONAL',universityCode:string)=>Promise<void>}) {
 const [mode,setMode]=useState<'PLATFORM'|'INSTITUTIONAL'>('PLATFORM'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[universityCode,setUniversityCode]=useState(''),[error,setError]=useState(''),[loading,setLoading]=useState(false)
 return <div className="auth-screen"><form className="auth-card" onSubmit={async e=>{e.preventDefault();setLoading(true);setError('');try{await onLogin(email,password,mode,universityCode)}catch(err){setError(err instanceof Error?err.message:'Login failed')}finally{setLoading(false)}}}><span className="auth-mark"><Command size={24}/></span><div className="eyebrow"><span className="eyebrow-dot"/>TECHCODER UNIVERSITY ERP</div><h1>{mode==='PLATFORM'?'Super Admin sign in':'University user sign in'}</h1><p>{mode==='PLATFORM'?'Use the platform administrator account.':'Use the university code and account provided by your university administrator.'}</p><div className="auth-mode-switch"><button type="button" className={mode==='PLATFORM'?'button button-primary':'outline-button'} onClick={()=>{setMode('PLATFORM');setError('')}}>Super Admin</button><button type="button" className={mode==='INSTITUTIONAL'?'button button-primary':'outline-button'} onClick={()=>{setMode('INSTITUTIONAL');setError('')}}>University user</button></div>{error&&<div className="platform-error" role="alert">{error}</div>}{mode==='INSTITUTIONAL'&&<label>University code<input required value={universityCode} onChange={e=>setUniversityCode(e.target.value.toUpperCase())} placeholder="TCU-XXXXXXXX"/></label>}<label>Email address<input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@university.edu"/></label><label>Password<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password"/></label><button className="button button-primary" disabled={loading}>{loading?<LoaderCircle size={16}/>:<ShieldCheck size={16}/>} {loading?'Signing in…':'Sign in securely'}</button><small>JWT authentication · University scoped access</small></form></div>
}

export default App
